from collections import deque
from typing import List

class Solution:
    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        N = 50
        def bfs(sx, sy):
            dist = [[-1]*N for _ in range(N)]
            dist[sx][sy] = 0
            dq = deque([(sx, sy)])
            dirs = [(1,2),(2,1),(-1,2),(-2,1),(1,-2),(2,-1),(-1,-2),(-2,-1)]
            while dq:
                x, y = dq.popleft()
                for dx, dy in dirs:
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < N and 0 <= ny < N and dist[nx][ny] < 0:
                        dist[nx][ny] = dist[x][y] + 1
                        dq.append((nx, ny))
            return dist

        n = len(positions)
        # node 0 = knight start, nodes 1..n = pawns
        pts = [(kx, ky)] + [(p[0], p[1]) for p in positions]
        D = [[0]*(n+1) for _ in range(n+1)]
        for a in range(n+1):
            d = bfs(pts[a][0], pts[a][1])
            for b in range(n+1):
                D[a][b] = d[pts[b][0]][pts[b][1]]

        full = (1 << n) - 1
        # f[mask][last] : mask = remaining pawns, last in 0..n (0 = knight start)
        # turn determined by number of captured = n - popcount(mask)
        f = [[0]*(n+1) for _ in range(1 << n)]
        pc = [bin(m).count('1') for m in range(1 << n)]
        for mask in range(1, 1 << n):
            # Alice moves if captured count is even
            alice = ((n - pc[mask]) % 2 == 0)
            for last in range(n+1):
                best = None
                for i in range(n):
                    if mask >> i & 1:
                        v = D[last][i+1] + f[mask ^ (1 << i)][i+1]
                        if best is None:
                            best = v
                        elif alice:
                            if v > best: best = v
                        else:
                            if v < best: best = v
                f[mask][last] = best
        return f[full][0]
