import json

KMOVES = [(1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)]


def _knight_dist(a, b):
    # Plain BFS on the empty 50x50 board (pawns do not block the knight).
    if a == b:
        return 0
    seen = {a: 0}
    q = deque([a])
    while q:
        x, y = q.popleft()
        for dx, dy in KMOVES:
            nx, ny = x + dx, y + dy
            if 0 <= nx < 50 and 0 <= ny < 50 and (nx, ny) not in seen:
                seen[(nx, ny)] = seen[(x, y)] + 1
                if (nx, ny) == b:
                    return seen[(nx, ny)]
                q.append((nx, ny))
    return None


@st.composite
def gen(draw):
    kx = draw(st.integers(0, 49))
    ky = draw(st.integers(0, 49))
    n = draw(st.integers(1, 5))
    small = draw(st.booleans())
    coord = st.integers(0, 4) if small else st.integers(0, 49)
    cells = draw(st.lists(st.tuples(coord, coord), min_size=n, max_size=n, unique=True))
    cells = [list(c) for c in cells if list(c) != [kx, ky]]
    if not cells:
        cells = [[(kx + 1) % 50, ky]]
    return f"{kx}\n{ky}\n{json.dumps(cells)}\n"


