            return False
        seen = set()
        for p in pos:
            if not isinstance(p, list) or len(p) != 2:
                return False
            x, y = p
            if type(x) is not int or type(y) is not int:
                return False
            if not (0 <= x <= 49 and 0 <= y <= 49):
