def ref(inp):
    lines = inp.strip().split("\n")
    kx = json.loads(lines[0])
    ky = json.loads(lines[1])
    pos = [tuple(p) for p in json.loads(lines[2])]
    n = len(pos)

    # d[i][j]: moves from pawn i (or knight start when i == n) to pawn j
    def dist_from(i, j):
        src = (kx, ky) if i == n else pos[i]
        return _knight_dist(src, pos[j])

    # Minimax over (last captured index, remaining mask).
    # Alice (maximizer) moves when an even number of pawns has been captured.
    memo = {}

    def solve(cur, mask):
        if mask == 0:
            return 0
        key = (cur, mask)
        if key in memo:
            return memo[key]
        captured = n - bin(mask).count("1")
        alice = (captured % 2 == 0)
        best = None
        for j in range(n):
            if mask & (1 << j):
                val = dist_from(cur, j) + solve(j, mask & ~(1 << j))
                if best is None:
                    best = val
                elif alice:
                    best = max(best, val)
                else:
                    best = min(best, val)
        memo[key] = best
        return best

    full = (1 << n) - 1
    return json.dumps(solve(n, full))
